import {trialState,trialsReady} from './court-trials.js?v=0.90.52';
import {COURT_RAIDERS,pendingCourtRaider,courtRaidCleared,installCourtRaiders,installCourtRaidTrainers} from './court-raiders.js?v=0.90.52';
import {legalForm,legalMoves} from './route-roster.js?v=0.90.52';
import {claimChoiceReward,choiceRewardText} from './choice-rewards.js?v=0.90.52';
import {courtState} from './paladin-roaming.js?v=0.90.52';
export const COURT_ROOMS=['courtTurn','bannerwood','courtProcession','courtPlinths','crownfall','courtApproach','emptyThrone'];
export const COURT_TITLES=['The Forgotten Turn','Bannerwood','The Broken Procession','The Thirteen Plinths','Crownfall Ravine','The Sceptre Road','The Empty Throne'];
export const COURT_COMMANDER='TRN-COURT-HUGH';
export const COURT_SEALS=[
 {key:'crown',label:'Tempered Crown',cat:'Karolion',type:'STEEL'},
 {key:'ember',label:'Banked Ember',cat:'Fieraguar',type:'FIRE'},
 {key:'night',label:'Unbarred Night',cat:'Ganelurk',type:'DARK'},
 {key:'bough',label:'Living Bough',cat:'Olivynx',type:'GRASS'},
 {key:'spring',label:'Shared Spring',cat:'Huonquet',type:'WATER'},
 {key:'thaw',label:'Thawing Shield',cat:'Ogyon',type:'ICE'}
];
export const COURT_INSCRIPTIONS={
 courage:{label:'The broken shield',text:'The six stewards laid down their Marks in turn, each only once. The last place belonged to the keeper of the hunted night. The tempered crown stood immediately before that keeper. Even Karolion could not place his own duty above the court’s agreement.'},
 judgement:{label:'The two petitioners',text:'Two other Marks lay between Huonquet’s offering and Fieraguar’s later offering. Olivynx followed Huonquet immediately: no sheltered grove could take its water before the spring’s creatures had enough. Read the Marks of Honour to know the stewards by their signs.'},
 mercy:{label:'The open gate',text:'Ogyon stood after Olivynx but before Fieraguar. Winter had to loosen before the cleansing burn could be banked. No promise was accepted until all six were made. When every steward’s place was right, the trees lowered their branches.'}
};
const OATH_ORDER=['spring','bough','thaw','ember','crown','night'];
export function readCourtInscription(state,key){const q=courtState(state);if(!q.accepted||!COURT_INSCRIPTIONS[key])return false;if(!q.inscriptions.includes(key))q.inscriptions.push(key);return true;}
export function pressCourtSeal(state,key){const q=courtState(state);if(!q.accepted||q.puzzle||q.inscriptions.length<3||!trialsReady(state)||!COURT_SEALS.some(s=>s.key===key)||q.sequence.includes(key))return {ok:false};q.sequence.push(key);if(q.sequence.length<6)return {ok:true,held:q.sequence.length};const solved=q.sequence.every((v,i)=>v===OATH_ORDER[i]);if(solved)q.puzzle=true;else{q.sequence=[];q.failedOaths=(q.failedOaths||0)+1;}return {ok:true,solved,reset:!solved};}
export function acceptCourt(state){const q=courtState(state);if(q.accepted)return false;q.accepted=true;return true;}
export function prepareCourtRelease(state,choice){const q=courtState(state);if(!q.commander||!COURT_RAIDERS.every(r=>courtRaidCleared(state,r))||q.released||q.releasePending||!['break','dismantle'].includes(choice))return false;q.choice=choice;q.releasePending=true;return true;}
export function finishCourtRelease(state){const q=courtState(state);if(!q.releasePending||q.released)return false;q.releasePending=false;q.released=true;q.regaliaTaken=true;claimChoiceReward(state,'court',q.choice);return true;}
export function courtGateOpen(state,gate){const q=courtState(state),raid=COURT_RAIDERS.find(r=>r.gate===gate);if(raid&&!courtRaidCleared(state,raid))return false;if(gate==='court-entry')return !!state.fates?.['LDR-03']||q.accepted||q.released;if(gate==='court-next-1'&&!trialState(state).channels.solved)return false;if(gate==='court-next-2'&&!trialState(state).wardens.solved)return false;if(gate==='court-next-3')return q.puzzle;if(gate==='court-next-5')return q.commander;if(gate==='court-shortcut'||gate==='court-shortcut-return')return q.released;return true;}
export function courtGateHint(state,gate){
 if(gate==='court-shortcut'||gate==='court-shortcut-return')return 'A force field blocks the rootway. The air shines like glass between the trees; the ward cannot be opened from this side. A faint trail leads north from Western Orchards into the old royal road.';
 if(gate==='court-entry')return 'Settle the Cybressa provost’s fate, then take the northern old royal road from Western Orchards to Scout Agnes at the Forgotten Turn.';
 const raid=COURT_RAIDERS.find(r=>r.gate===gate);if(raid&&!courtRaidCleared(state,raid))return raid.name+' holds this stretch of road. Speak to them before trying to pass. The western return remains open.';
 if(gate==='court-next-1'&&!trialState(state).channels.solved)return 'The roots are dry. Restore the Shared Spring at the carved channel table in Bannerwood; water every habitat without flooding the nesting ground.';
 if(gate==='court-next-2'&&!trialState(state).wardens.solved)return 'Fire and frost grip the arch. Guide the two linked guardians to their matching sanctuaries at the Broken Procession.';
 if(gate==='court-next-3')return !trialsReady(state)?'The arch needs both restored duties: the Shared Spring in Bannerwood and the elemental wardens in the Broken Procession.':'The final roots hold the arch shut. Read the three reliefs here and complete Karolion’s oath in the order his duties were performed.';
 return 'Hugh de Mowbray waits beside the two burgundy banners, just west of the eastern root arch. He means to test the knightly duty he has spent years researching.';
}
export function courtBlocked(state,room,x,y){return room==='courtPlinths'&&!courtState(state).puzzle&&x===43&&y>=7&&y<=11||room==='courtApproach'&&!courtState(state).commander&&x===43&&y>=7&&y<=11;}
export function courtObjective(state,room){if(!COURT_ROOMS.includes(room))return null;const q=courtState(state),i=COURT_ROOMS.indexOf(room),trials=trialState(state);
 const toward=(target,text)=>({spot:i===target?null:i<target?'court-next-'+i:'court-back-'+i,text});
 if(!q.accepted)return room==='courtTurn'?{spot:'court-scout',text:'Speak to Agnes beside the broken monument'}:toward(0,'Return west to Agnes at the Forgotten Turn');
 if(q.released)return {spot:null,text:'The court is roaming · the rootway shortcut is open'};
 if(q.releasePending)return room==='emptyThrone'?{spot:'court-regalia',text:'Return to the orb and sceptre'}:toward(6,'Follow the road east to the Empty Throne');
 const raid=COURT_RAIDERS.find(r=>!courtRaidCleared(state,r)),raidIndex=raid?COURT_ROOMS.indexOf(raid.room):-1;if(raid&&raidIndex<=i)return raidIndex===i?{spot:raid.id,text:raid.character==='REV-DARIUS'?'Darius has reached the inner road':'The Common Cause holds the road · speak to '+raid.name.split(' · ')[0]}:toward(raidIndex,'Return west to the Common Cause post at '+COURT_TITLES[raidIndex]);
 if(!q.puzzle){if(!trials.channels.solved)return room==='bannerwood'?{spot:'court-root-channels',text:'Restore Huonquet’s Shared Spring'}:toward(1,'Restore the Shared Spring in Bannerwood');if(!trials.wardens.solved)return room==='courtProcession'?{spot:'court-twin-wardens',text:'Balance Fieraguar and Ogyon’s linked wardens'}:toward(2,'Reach the elemental wardens at the Broken Procession');if(room!=='courtPlinths')return toward(3,i<3?'Follow the road east to the Thirteen Plinths':'Return west to the Thirteen Plinths');const key=Object.keys(COURT_INSCRIPTIONS).find(k=>!q.inscriptions.includes(k));return {spot:key?'court-inscription-'+key:'court-honours',text:key?'Read the three reliefs · '+q.inscriptions.length+'/3':'Complete the oath in the order shown by the reliefs'};}
 if(raid)return toward(raidIndex,'Follow the road to the Common Cause post at '+COURT_TITLES[raidIndex]);
 if(!q.commander)return room==='courtApproach'?{spot:COURT_COMMANDER,text:'Challenge Hugh beside the eastern burgundy banners'}:toward(5,i<5?'Continue east through Crownfall Ravine to Hugh':'Return west to Hugh on the Sceptre Road');
 return room==='emptyThrone'?{spot:'court-regalia',text:'Examine the ancient regalia cradle'}:toward(6,'Hugh is defeated · continue east to the Empty Throne');
}

export function courtSpots(spots,state){const q=courtState(state);return spots.filter(s=>!(s.id.startsWith('court-shortcut')&&!q.released)&&!(s.courtRaider&&courtRaidCleared(state,s.id))).map(s=>s.id==='court-regalia'&&q.released?{...s,label:'The empty regalia cradle'}:s);}
export function courtRoute(room){const i=COURT_ROOMS.indexOf(room);if(i<0)return null;const lo=32+Math.min(5,i);return {room,area:{id:'COURT-'+i,rate:i===6?'LOW':'NORMAL'},tables:['DAY','NIGHT'].map(phase=>({id:room+'-'+phase,phase,slots:[{species_id:'042',min_level:lo,max_level:lo+2,weight:45,authoredSlot:true},{species_id:'139',min_level:lo,max_level:lo+2,weight:35,authoredSlot:true},{species_id:'295',min_level:lo,max_level:lo+2,weight:20,authoredSlot:true}]}))};}
export function installCourtWorld(maps){const parent=maps.orchardVerge;parent.sidePaths??=[];parent.sidePaths.push({gateId:'court-shortcut-return',points:[[38,23],[40,23],[40,28]]});parent.gates.push({id:'court-shortcut-return',label:'Rootway to the Empty Throne',x:40,y:28,to:'emptyThrone',arrival:[44,23,'left'],door:true,action:'court-gate'});parent.sidePaths.push({gateId:'court-entry',points:[[25,9],[23,9],[23,4]]});parent.gates.push({id:'court-entry',label:'The old royal road · optional Lv. 32–42',x:23,y:4,to:'courtTurn',arrival:[3,17,'right'],door:true,action:'court-gate'});parent.spots.push({id:'court-road-sign',label:'Old royal road marker',x:25,y:6,routeSign:true});
 COURT_ROOMS.forEach((room,i)=>{const roads=[[[1,17],[11,17],[11,8],[24,8],[24,24],[36,24],[36,9],[46,9]],[[1,17],[9,17],[9,25],[20,25],[20,8],[32,8],[32,18],[40,18],[40,9],[46,9]],[[1,17],[8,17],[8,8],[19,8],[19,24],[32,24],[32,15],[40,15],[40,9],[46,9]],[[1,17],[11,17],[11,25],[35,25],[35,9],[46,9]],[[1,17],[8,17],[8,26],[19,26],[19,9],[29,9],[29,24],[39,24],[39,9],[46,9]],[[1,17],[10,17],[10,8],[22,8],[22,24],[32,24],[32,9],[46,9]],[[1,17],[24,17],[24,12],[36,12],[36,9],[46,9]]];const road=roads[i];maps[room]={name:COURT_TITLES[i],area:'COURT-'+i,terrain:'court',courtIndex:i,bloom:false,road,grass:i===6?[]:[[5,21,9,27],[15,11,21,16],[27,5,33,13],[38,19,43,26]],props:[],sidePaths:[{points:[[11,17],[17,17]]},{points:[[24,24],[30,24]]}],spots:[{id:'area-sign',label:COURT_TITLES[i]+' marker',x:5,y:18,routeSign:true}],gates:[{id:'court-back-'+i,label:i?COURT_TITLES[i-1]:'Return to Western Orchards',x:1,y:17,to:i?COURT_ROOMS[i-1]:'orchardVerge',arrival:i?[44,9,'left']:[23,6,'down'],door:true,action:'court-gate'},...(i<6?[{id:'court-next-'+i,label:COURT_TITLES[i+1],x:46,y:9,to:COURT_ROOMS[i+1],arrival:[3,17,'right'],door:true,action:'court-gate'}]:[])]};});
 maps.courtTurn.spots.push({id:'court-scout',label:'Scout Agnes de Clare',x:17,y:17,courtHuman:'scout',sprite:0},{id:'court-monument',label:'Broken royal monument',x:20,y:17});
 maps.bannerwood.spots.push({id:'court-banner',label:'A torn expedition banner',x:16,y:25},{id:'court-pack',label:'Scout’s abandoned pack',x:29,y:9});
 maps.courtProcession.spots.push({id:'court-orders',label:'Dropped expedition orders',x:28,y:24},{id:'court-footprints',label:'Scored paving stones',x:15,y:8});
 maps.courtPlinths.spots.push(...Object.entries(COURT_INSCRIPTIONS).map(([key,v],i)=>({id:'court-inscription-'+key,label:v.label,x:17+i*7,y:16})),...COURT_SEALS.map((v,i)=>({id:'court-seal-'+v.key,label:v.label+' seal',x:14+i*4,y:21})));maps.courtPlinths.sidePaths=[{points:[[11,17],[35,17]]},{points:[[14,17],[14,23],[35,23],[35,16]]}];

 maps.crownfall.spots.push({id:'court-rest',label:'Agnes’s sheltered camp',x:17,y:17,courtHuman:'scout',sprite:0},{id:'court-ravine-note',label:'A carving beneath the roots',x:30,y:24});
 maps.courtApproach.spots.push({id:COURT_COMMANDER,label:'Sir Hugh de Mowbray',x:39,y:9,courtHuman:'commander',sprite:0},{id:'court-camp-orders',label:'Commander’s field notes',x:26,y:24});
 maps.bannerwood.spots.push({id:'court-root-channels',label:'The Shared Spring · carved root channels',x:26,y:18});maps.courtProcession.spots.push({id:'court-twin-wardens',label:'Fire and Ice · linked guardian trial',x:25,y:16});maps.courtPlinths.spots.push({id:'court-honours',label:'The thirteen Marks of Honour',x:24,y:12});installCourtRaiders(maps);
 maps.emptyThrone.courtSanctuary=true;maps.emptyThrone.spots.push({id:'court-regalia',label:'The orb and sceptre',x:24,y:12},{id:'court-throne-inscription',label:'The empty throne',x:24,y:7});for(const key of COURT_ROOMS){const map=maps[key];for(const spot of map.spots){const nearest=map.road.reduce((a,b)=>Math.abs(a[0]-spot.x)+Math.abs(a[1]-spot.y)<Math.abs(b[0]-spot.x)+Math.abs(b[1]-spot.y)?a:b);map.sidePaths.push({points:[nearest,[spot.x,nearest[1]],[spot.x,spot.y]]});}}
 maps.emptyThrone.gates.push({id:'court-shortcut',label:'Rootway shortcut to Western Orchards',x:46,y:23,to:'orchardVerge',arrival:[40,26,'up'],door:true,action:'court-gate'});
}
export function installCourtTrainers(expansion,voices){installCourtRaidTrainers(expansion,voices);if(!expansion.trainers.some(t=>t.id===COURT_COMMANDER))expansion.trainers.push({id:COURT_COMMANDER,name:'Sir Hugh de Mowbray',portraitId:COURT_COMMANDER,role:'route',ai_tier:'Leader-lite',runtimeAuthored:true,team:['015','054','117','100','128','140'].map((id,i)=>{const level=38+Math.min(i,4),species_id=legalForm(id,level);return {slot:i+1,species_id,level,current_form_legal_move_ids:legalMoves(species_id,level)};})});voices[COURT_COMMANDER]={before:'I have read the old rolls until the ink swam. Karolion’s court sheltered the weak and held its own power in check. Our First Light blesses seized grain and calls obedience a virtue. If the thirteen still live, perhaps our knights can remember what honour asks of them. You have crossed their trials. Now let me see what you will do when strength answers back.',after:'You put your partners before your pride. I asked the same of my order and was told I had misunderstood obedience. There is a sealed chamber beyond the arch. I have never entered it. Whatever lies there, hear what the stewards guarded before asking them to follow.',repeat:'I know nothing of an orb or a sceptre. My research named the thirteen and their duties. Perhaps I should have asked what they wanted of us.'};}
